SELECT c.cinema_id , c.multiplex_id , c.area_id , c.cinema_name , c.cinema_addr , m.multiplex_name , a.area_name
  FROM cinema c
  JOIN multiplex m ON c.multiplex_id = m.multiplex_id
  JOIN area a ON c.area_id = a.area_id
 WHERE c.multiplex_id = #{multiplexId}
   AND c.area_id = #{areaId}

SELECT screen_id , multiplex_id , cinema_id , screen_name
FROM screen
WHERE multiplex_id = #{multiplexId}
  AND cinema_id = #{cinemaId}

SELECT *
FROM post
WHERE cinema_id = #{cinemaId}

    AND screen_id = #{screenId}

ORDER BY created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM post
WHERE cinema_id = #{cinemaId}

    AND screen_id = #{screenId}

SELECT post_id, COUNT(*) AS commentCount FROM comment WHERE post_id IN
#{id}
GROUP BY post_id
